  type: 'function',
  name: 'orderLookup',
  description: 'Look up an order',
  inputSchema: z.object({ orderId: z.string() }),
  execute: async ({ orderId }) => {
    const order = findOrder(orderId);
    return { status: order?.status };
  },
};

