]);

const result = await generateText({
  model,
  system: 'Test system',
  tools: { orderLookup },
  maxSteps: 4,
  messages: [{ role: 'user', content: 'What is the status of order A100?' }],
});

console.log('result.text:', result.text);
console.log('result.response.messages length:', result.response.messages.length);
result.response.messages.forEach((msg, i) => {
  console.log(\`Message \${i}:\`, msg.role, 'content:', typeof msg.content, Array.isArray(msg.content) ? msg.content.length : 'N/A');
  if (Array.isArray(msg.content)) {
    msg.content.forEach((c, j) => {
      console.log(\`  Content \${j}:\`, c.type);
    });
  }
});
